21	/// Upper bound on the bytes read for a single OSV record (one zip entry
22	/// or one directory file). OSV advisories are a few KB; this cap only
23	/// exists so a crafted database can't exhaust memory at startup.
24	const MAX_OSV_RECORD_BYTES: u64 = 16 * 1024 * 1024;
