[metadata] {"filePath": "/workspace/repo/pnpr/crates/pnpr/src/server.rs", "oldString": "fn packument_bytes_response(bytes: Vec<u8>, content_type: &'static str) -> Response {", "newString": "/// Remove every version entry the OSV database flags as vulnerable, plus
/// entries that fail an identity/semver sanity check, and reconcile the
/// `time` map and `dist-tags` object with the removals. Returns the set
/// of removed version keys.
///
/// An entry is dropped when any of these hold:
/// * its key is listed as vulnerable for this package in the OSV index;
/// * the entry's own `version` field doesn't match its key (identity
///   mismatch);
/// * the key isn't a valid semver string.
///
/// The identity/semver checks apply regardless of OSV status — such an
/// entry is ineligible to serve either way. The whole pass is a no-op
/// (returning an empty set) when the OSV database is disabled.
fn filter_packument_versions(
    doc: &mut Value,
    name: &PackageName,
    osv_index: Option<&Arc<crate::resolver::OsvIndex>>,
) -> std::collections::HashSet<String> {
    let mut removed = std::collections::HashSet::new();
    let Some(osv_index) = osv_index else {
        return removed;
    };

    if let Some(versions) = doc.get_mut("versions").and_then(Value::as_object_mut) {
        versions.retain(|version_key, entry| {
            let keep = version_entry_is_eligible(version_key, entry)
                && !osv_index.is_vulnerable(name.as_str(), version_key);
            if !keep {
                removed.insert(version_key.clone());
            }
            keep
        });
    }
    if removed.is_empty() {
        return removed;
    }
    // A removed version's `time` and `dist-tags` references would
    // otherwise dangle, still advertising the pulled release.
    if let Some(time) = doc.get_mut("time").and_then(Value::as_object_mut) {
        time.retain(|key, _| !removed.contains(key));
    }
    if let Some(tags) = doc.get_mut("dist-tags").and_then(Value::as_object_mut) {
        tags.retain(|_, target| target.as_str().is_none_or(|version| !removed.contains(version)));
    }
    removed
}

/// Whether a `versions` entry is eligible to serve on its own merits,
/// independent of OSV status: its key must be a valid semver string and
/// must match the `version` field inside the entry. A mismatch or a
/// non-semver key marks a malformed/ambiguous entry that is dropped.
fn version_entry_is_eligible(version_key: &str, entry: &Value) -> bool {
    if entry.get("version").and_then(Value::as_str) != Some(version_key) {
        return false;
    }
    node_semver::Version::parse(version_key).is_ok()
}

